window.Sandbox.compat.team04Markup = "<div class=\"os-team04\">\r\n\r\n    <!-- =========================================\r\n         HEADER\r\n         ========================================= -->\r\n    <header>\r\n\r\n        <h1>\r\n            Round Robin CPU Scheduling\r\n        </h1>\r\n\r\n        <!-- =========================================\r\n             ABOUT ROUND ROBIN CPU SCHEDULING\r\n             EVERYTHING IS INSIDE HEADER\r\n             ========================================= -->\r\n\r\n        <div class=\"about-round-robin\">\r\n\r\n            <h2>\r\n                About Round Robin CPU Scheduling\r\n            </h2>\r\n\r\n            <!-- DEFINITION -->\r\n\r\n            <h3>\r\n                Definition\r\n            </h3>\r\n\r\n            <p>\r\n                Round Robin is a preemptive CPU scheduling algorithm\r\n                in which each process is given a fixed amount of CPU\r\n                time called a <strong>Time Quantum</strong>. Processes\r\n                are executed in a circular order. When a process uses\r\n                its Time Quantum, it is moved to the back of the\r\n                Ready Queue if it still has remaining execution time.\r\n            </p>\r\n\r\n            <!-- HOW ROUND ROBIN WORKS -->\r\n\r\n            <h3>\r\n                How Round Robin Works\r\n            </h3>\r\n\r\n            <ol>\r\n\r\n                <li>\r\n                    Processes enter the Ready Queue according to\r\n                    their arrival time.\r\n                </li>\r\n\r\n                <li>\r\n                    The CPU selects the first process from the\r\n                    Ready Queue.\r\n                </li>\r\n\r\n                <li>\r\n                    The selected process executes for a maximum of\r\n                    one Time Quantum.\r\n                </li>\r\n\r\n                <li>\r\n                    If the process finishes before the Time Quantum\r\n                    expires, it leaves the Ready Queue.\r\n                </li>\r\n\r\n                <li>\r\n                    If the process is not finished, it is moved to\r\n                    the back of the Ready Queue.\r\n                </li>\r\n\r\n                <li>\r\n                    The CPU then selects the next process in the queue.\r\n                </li>\r\n\r\n                <li>\r\n                    This process continues until all processes\r\n                    are completed.\r\n                </li>\r\n\r\n            </ol>\r\n\r\n            <!-- IMPORTANT TERMS -->\r\n\r\n            <h3>\r\n                Important Terms\r\n            </h3>\r\n\r\n            <ul>\r\n\r\n                <li>\r\n                    <strong>Time Quantum:</strong>\r\n                    The maximum amount of CPU time given to a process\r\n                    during one turn.\r\n                </li>\r\n\r\n                <li>\r\n                    <strong>Ready Queue:</strong>\r\n                    The queue containing processes waiting for CPU execution.\r\n                </li>\r\n\r\n                <li>\r\n                    <strong>Preemption:</strong>\r\n                    The running process can be interrupted when its\r\n                    Time Quantum expires.\r\n                </li>\r\n\r\n                <li>\r\n                    <strong>Context Switching:</strong>\r\n                    The CPU switches from one process to another process.\r\n                </li>\r\n\r\n                <li>\r\n                    <strong>Arrival Time:</strong>\r\n                    The time at which a process enters the Ready Queue.\r\n                </li>\r\n\r\n                <li>\r\n                    <strong>Burst Time:</strong>\r\n                    The total CPU time required by a process for execution.\r\n                </li>\r\n\r\n            </ul>\r\n\r\n            <!-- WORKING EXAMPLE -->\r\n\r\n            <h3>\r\n                Working Example\r\n            </h3>\r\n\r\n            <p>\r\n                Consider four processes P1, P2, P3 and P4 with a\r\n                Time Quantum of 2 units. The CPU first executes P1\r\n                for up to 2 units. If P1 is not completed, it moves\r\n                to the back of the Ready Queue. The CPU then executes\r\n                P2 for up to 2 units, followed by P3 and P4. The same\r\n                circular process continues until all processes are completed.\r\n            </p>\r\n\r\n            <!-- CHARACTERISTICS -->\r\n\r\n            <h3>\r\n                Characteristics of Round Robin\r\n            </h3>\r\n\r\n            <ul>\r\n\r\n                <li>\r\n                    It is a <strong>preemptive</strong> scheduling algorithm.\r\n                </li>\r\n\r\n                <li>\r\n                    It uses a <strong>Time Quantum</strong>.\r\n                </li>\r\n\r\n                <li>\r\n                    Processes are handled using a\r\n                    <strong>circular Ready Queue</strong>.\r\n                </li>\r\n\r\n                <li>\r\n                    Each process gets an opportunity to use the CPU.\r\n                </li>\r\n\r\n                <li>\r\n                    A process may execute multiple times before completing.\r\n                </li>\r\n\r\n                <li>\r\n                    Context switching occurs when the CPU moves\r\n                    between processes.\r\n                </li>\r\n\r\n            </ul>\r\n\r\n            <!-- SCHEDULING PERFORMANCE TERMS -->\r\n\r\n            <h3>\r\n                Scheduling Performance Terms\r\n            </h3>\r\n\r\n            <ul>\r\n\r\n                <li>\r\n                    <strong>Completion Time:</strong>\r\n                    The time at which a process finishes execution.\r\n                </li>\r\n\r\n                <li>\r\n                    <strong>Turnaround Time:</strong>\r\n                    The total time from the arrival of a process\r\n                    until its completion.\r\n                </li>\r\n\r\n                <li>\r\n                    <strong>Waiting Time:</strong>\r\n                    The total time a process spends waiting in the\r\n                    Ready Queue.\r\n                </li>\r\n\r\n                <li>\r\n                    <strong>Response Time:</strong>\r\n                    The time from process arrival until it first\r\n                    gets CPU execution.\r\n                </li>\r\n\r\n            </ul>\r\n\r\n            <!-- ADVANTAGES -->\r\n\r\n            <h3>\r\n                Advantages\r\n            </h3>\r\n\r\n            <ul>\r\n\r\n                <li>\r\n                    Fair CPU time is given to each process.\r\n                </li>\r\n\r\n                <li>\r\n                    Provides good response time for interactive systems.\r\n                </li>\r\n\r\n                <li>\r\n                    Prevents starvation of processes.\r\n                </li>\r\n\r\n                <li>\r\n                    Simple and easy to implement.\r\n                </li>\r\n\r\n                <li>\r\n                    Suitable for time-sharing operating systems.\r\n                </li>\r\n\r\n            </ul>\r\n\r\n            <!-- DISADVANTAGES -->\r\n\r\n            <h3>\r\n                Disadvantages\r\n            </h3>\r\n\r\n            <ul>\r\n\r\n                <li>\r\n                    Performance depends on the selected Time Quantum.\r\n                </li>\r\n\r\n                <li>\r\n                    A very small Time Quantum causes more context switching.\r\n                </li>\r\n\r\n                <li>\r\n                    A very large Time Quantum makes Round Robin behave\r\n                    more like FCFS.\r\n                </li>\r\n\r\n                <li>\r\n                    Context switching creates additional overhead.\r\n                </li>\r\n\r\n                <li>\r\n                    It may result in higher average waiting time in\r\n                    some cases.\r\n                </li>\r\n\r\n            </ul>\r\n\r\n        </div>\r\n\r\n    </header>\r\n\r\n\r\n    <!-- =========================================\r\n         SCHEDULING CONTROLS\r\n         ========================================= -->\r\n\r\n    <section>\r\n\r\n        <h2>\r\n            Scheduling Controls\r\n        </h2>\r\n\r\n        <label for=\"quantum\">\r\n            Time Quantum:\r\n        </label>\r\n\r\n        <input\r\n            type=\"number\"\r\n            id=\"quantum\"\r\n            value=\"2\"\r\n            min=\"1\"\r\n            step=\"1\"\r\n        >\r\n\r\n        <span>\r\n            units\r\n        </span>\r\n\r\n        <br>\r\n        <br>\r\n\r\n        <button\r\n            id=\"runButton\"\r\n            type=\"button\"\r\n        >\r\n            Run Round Robin\r\n        </button>\r\n\r\n        <button\r\n            id=\"resetButton\"\r\n            type=\"button\"\r\n        >\r\n            Reset\r\n        </button>\r\n\r\n    </section>\r\n\r\n\r\n    <!-- =========================================\r\n         PROCESS DETAILS\r\n         ========================================= -->\r\n\r\n    <section>\r\n\r\n        <h2>\r\n            Process Details\r\n        </h2>\r\n\r\n        <label for=\"processCount\">\r\n            Number of Processes:\r\n        </label>\r\n\r\n        <input\r\n            type=\"number\"\r\n            id=\"processCount\"\r\n            value=\"4\"\r\n            min=\"1\"\r\n            max=\"20\"\r\n            step=\"1\"\r\n        >\r\n\r\n        <button\r\n            id=\"updateProcessesButton\"\r\n            type=\"button\"\r\n        >\r\n            Update Processes\r\n        </button>\r\n\r\n        <br>\r\n        <br>\r\n\r\n        <table>\r\n\r\n            <thead>\r\n\r\n                <tr>\r\n\r\n                    <th>\r\n                        Process ID\r\n                    </th>\r\n\r\n                    <th>\r\n                        Arrival Time\r\n                    </th>\r\n\r\n                    <th>\r\n                        Burst Time\r\n                    </th>\r\n\r\n                </tr>\r\n\r\n            </thead>\r\n\r\n            <tbody id=\"processTableBody\">\r\n\r\n                <tr>\r\n\r\n                    <td>\r\n                        <input\r\n                            class=\"pid\"\r\n                            value=\"P1\"\r\n                        >\r\n                    </td>\r\n\r\n                    <td>\r\n                        <input\r\n                            class=\"arrival\"\r\n                            type=\"number\"\r\n                            value=\"0\"\r\n                            min=\"0\"\r\n                        >\r\n                    </td>\r\n\r\n                    <td>\r\n                        <input\r\n                            class=\"burst\"\r\n                            type=\"number\"\r\n                            value=\"5\"\r\n                            min=\"1\"\r\n                        >\r\n                    </td>\r\n\r\n                </tr>\r\n\r\n                <tr>\r\n\r\n                    <td>\r\n                        <input\r\n                            class=\"pid\"\r\n                            value=\"P2\"\r\n                        >\r\n                    </td>\r\n\r\n                    <td>\r\n                        <input\r\n                            class=\"arrival\"\r\n                            type=\"number\"\r\n                            value=\"1\"\r\n                            min=\"0\"\r\n                        >\r\n                    </td>\r\n\r\n                    <td>\r\n                        <input\r\n                            class=\"burst\"\r\n                            type=\"number\"\r\n                            value=\"3\"\r\n                            min=\"1\"\r\n                        >\r\n                    </td>\r\n\r\n                </tr>\r\n\r\n                <tr>\r\n\r\n                    <td>\r\n                        <input\r\n                            class=\"pid\"\r\n                            value=\"P3\"\r\n                        >\r\n                    </td>\r\n\r\n                    <td>\r\n                        <input\r\n                            class=\"arrival\"\r\n                            type=\"number\"\r\n                            value=\"2\"\r\n                            min=\"0\"\r\n                        >\r\n                    </td>\r\n\r\n                    <td>\r\n                        <input\r\n                            class=\"burst\"\r\n                            type=\"number\"\r\n                            value=\"4\"\r\n                            min=\"1\"\r\n                        >\r\n                    </td>\r\n\r\n                </tr>\r\n\r\n                <tr>\r\n\r\n                    <td>\r\n                        <input\r\n                            class=\"pid\"\r\n                            value=\"P4\"\r\n                        >\r\n                    </td>\r\n\r\n                    <td>\r\n                        <input\r\n                            class=\"arrival\"\r\n                            type=\"number\"\r\n                            value=\"3\"\r\n                            min=\"0\"\r\n                        >\r\n                    </td>\r\n\r\n                    <td>\r\n                        <input\r\n                            class=\"burst\"\r\n                            type=\"number\"\r\n                            value=\"2\"\r\n                            min=\"1\"\r\n                        >\r\n                    </td>\r\n\r\n                </tr>\r\n\r\n            </tbody>\r\n\r\n        </table>\r\n\r\n    </section>\r\n\r\n\r\n    <!-- =========================================\r\n         READY QUEUE\r\n         ========================================= -->\r\n\r\n    <section>\r\n\r\n        <h2>\r\n            Ready Queue\r\n        </h2>\r\n\r\n        <div\r\n            class=\"ready-queue\"\r\n            id=\"readyQueue\"\r\n        >\r\n        </div>\r\n\r\n    </section>\r\n\r\n\r\n    <!-- =========================================\r\n         GANTT CHART\r\n         ========================================= -->\r\n\r\n    <section>\r\n\r\n        <h2>\r\n            Gantt Chart\r\n        </h2>\r\n\r\n        <div\r\n            class=\"gantt-chart\"\r\n            id=\"ganttChart\"\r\n        >\r\n            Gantt Chart will appear here\r\n        </div>\r\n\r\n    </section>\r\n\r\n\r\n    <!-- =========================================\r\n         RESULTS\r\n         ========================================= -->\r\n\r\n    <section>\r\n\r\n        <h2>\r\n            Scheduling Results\r\n        </h2>\r\n\r\n        <table>\r\n\r\n            <thead>\r\n\r\n                <tr>\r\n\r\n                    <th>\r\n                        Process\r\n                    </th>\r\n\r\n                    <th>\r\n                        Completion Time\r\n                    </th>\r\n\r\n                    <th>\r\n                        Turnaround Time\r\n                    </th>\r\n\r\n                    <th>\r\n                        Waiting Time\r\n                    </th>\r\n\r\n                </tr>\r\n\r\n            </thead>\r\n\r\n            <tbody id=\"resultsBody\">\r\n            </tbody>\r\n\r\n        </table>\r\n\r\n\r\n        <div class=\"average-results\">\r\n\r\n            <p>\r\n\r\n                <strong>\r\n                    Average Waiting Time:\r\n                </strong>\r\n\r\n                <span id=\"avgWaiting\">\r\n                    \u2014\r\n                </span>\r\n\r\n                units\r\n\r\n            </p>\r\n\r\n\r\n            <p>\r\n\r\n                <strong>\r\n                    Average Turnaround Time:\r\n                </strong>\r\n\r\n                <span id=\"avgTurnaround\">\r\n                    \u2014\r\n                </span>\r\n\r\n                units\r\n\r\n            </p>\r\n\r\n        </div>\r\n\r\n    </section>\r\n\r\n\r\n    <!-- =========================================\r\n         FOOTER\r\n         ========================================= -->\r\n\r\n    <footer>\r\n\r\n        <p>\r\n            Round Robin CPU Scheduling\r\n        </p>\r\n\r\n    </footer>\r\n\r\n\r\n</div>";
